namespace HabitFlow.Domain;
public interface IUserRepository{Task<User?> GetByEmailAsync(string email,CancellationToken ct=default);Task<User?> GetByIdAsync(Guid id,CancellationToken ct=default);Task CreateAsync(User user,CancellationToken ct=default);Task UpdateLastLoginAsync(Guid id,DateTime at,CancellationToken ct=default);Task<IReadOnlyList<User>> SearchAsync(string? email,CancellationToken ct=default);} 
public interface IHabitRepository{Task<int> CountActiveAsync(Guid userId,CancellationToken ct=default);Task<IReadOnlyList<Habit>> ListAsync(Guid userId,bool includeArchived=false,CancellationToken ct=default);Task CreateAsync(Habit habit,CancellationToken ct=default);Task ArchiveAsync(Guid id,Guid userId,bool archived,CancellationToken ct=default);} 
public interface IHabitCompletionRepository{Task<IReadOnlyList<HabitCompletion>> ListAsync(Guid userId,DateOnly from,DateOnly to,CancellationToken ct=default);Task CompleteAsync(HabitCompletion completion,CancellationToken ct=default);Task UncompleteAsync(Guid habitId,Guid userId,DateOnly date,CancellationToken ct=default);} 
public interface IAuditRepository{Task AddSystemAsync(SystemAuditLog log,CancellationToken ct=default);Task AddAdminAsync(AdminAuditLog log,CancellationToken ct=default);} 
